import type { Metadata, Viewport } from "next";
import type { CSSProperties } from "react";
import localFont from "next/font/local";
import { GoogleAnalytics } from "@next/third-parties/google";
import { Analytics } from "@vercel/analytics/next";
import { SpeedInsights } from "@vercel/speed-insights/next";
import { Suspense } from "react";
import { ThemeAccess, readThemeAccess } from "@/components/theme-access";
import { ThemeRuntime } from "@/components/theme";
import "./theme-tokens.css";
import "./globals.css";
import "./compose-theme.css";
import "./workspace-theme.css";
import "./appearance-control.css";
import "./preview-highlight.css";
import { themeScript } from "@/lib/theme";
const PlusJakartaSans = localFont({
  src: "./fonts/PlusJakartaSans-Variable.ttf",
  variable: "--font-plus-jakarta",
  weight: "400 800",
  style: "normal",
  display: "swap",
  adjustFontFallback: false,
  fallback: ["system-ui", "sans-serif"],
});
const InterBlack = localFont({
  src: "../../public/fonts/inter/InterVariable.woff2",
  weight: "875",
  style: "normal",
  display: "swap",
  adjustFontFallback: false,
  fallback: ["system-ui", "sans-serif"],
});
const JetBrainsMono = localFont({
  src: "./fonts/JetBrainsMono-Variable.ttf",
  variable: "--font-jetbrains",
  weight: "400 500",
  style: "normal",
  display: "swap",
  adjustFontFallback: false,
  fallback: ["monospace"],
});
const SpaceGrotesk = localFont({
  src: "./fonts/SpaceGrotesk-Variable.ttf",
  variable: "--font-space-grotesk",
  weight: "500 700",
  style: "normal",
  display: "swap",
  adjustFontFallback: false,
  fallback: ["system-ui", "sans-serif"],
});
export const metadata: Metadata = {
  metadataBase: new URL("https://www.mailloop.in"),
  title: {
    default: "Mailloop — Make your next introduction",
    template: "%s | Mailloop",
  },
  description:
    "Personalized job outreach, sent individually from your own Gmail. Prepare your message, attach your resume, and keep every conversation in view.",
  openGraph: {
    title: "Mailloop",
    description: "A thoughtful introduction. A new opportunity.",
    siteName: "Mailloop",
    type: "website",
    images: [
      {
        url: "/social-logo.png",
        width: 1024,
        height: 1024,
        alt: "Mailloop logo",
      },
    ],
  },
  twitter: { card: "summary", images: ["/social-logo.png"] },
};
export const viewport: Viewport = { themeColor: "#f6f5fb" };
export default async function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const access = await readThemeAccess();
  return (
    <html
      suppressHydrationWarning
      lang="en"
      data-scroll-behavior="smooth"
      className={`${PlusJakartaSans.variable} ${JetBrainsMono.variable} ${SpaceGrotesk.variable} antialiased`}
    >
      <head>
        <script dangerouslySetInnerHTML={{ __html: themeScript(access) }} />
      </head>
      <body
        className="min-h-screen font-sans"
        style={
          {
            "--font-limit-banner": PlusJakartaSans.style.fontFamily,
            "--font-price": PlusJakartaSans.style.fontFamily,
            "--font-price-amount": InterBlack.style.fontFamily,
          } as CSSProperties
        }
      >
        <Suspense fallback={null}>
          <ThemeRuntime />
          <ThemeAccess />
        </Suspense>
        <a
          href="#main-content"
          className="fixed left-4 top-4 z-50 -translate-y-24 rounded-sm bg-primary px-4 py-3 text-primary-foreground focus:translate-y-0"
        >
          Skip to content
        </a>
        {children}
        <Analytics />
        <SpeedInsights />
      </body>
      <GoogleAnalytics gaId="G-JMR4H98NTK" />
    </html>
  );
}
